import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.DwAI3uWn.js";const u=JSON.parse('{"title":"proposal","description":"Pre-Act3","frontmatter":{"title":"proposal","description":"Pre-Act3","source":"docs/archive/source-material/proposal.md","category":"Archive","sourceUpdated":"2026-10-08T06:33:54+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/archive/source-material/proposal.md","filePath":"content/docs/archive/source-material/proposal.md"}'),n={name:"content/docs/archive/source-material/proposal.md"};function r(c,e,l,s,p,d){return t(),i("div",null,[...e[0]||(e[0]=[o('<div><h1 id="document-title">proposal<a class="header-anchor" href="#document-title" aria-label="Link to title">​</a></h1><p>Pre-Act3</p><p>Proposal #1 Chainy: A 3D World Educational Game for learning emerging Technology (Blockchain &amp; AI)</p><p>Group # 13</p><p>BSIT - GD - J4S</p><p>Group Members: Luis M. Cabrido Iii Sherwin P. Limosnero Sean Matthew Lee Narvaez Christian Jude N. Villaber</p><p>PROFESSOR: Michael M. Orozco</p><p>Proof of Concept (PoC)<br> The Proof of Concept validates that the core mechanics and educational concepts outlined for Chainy can be implemented effectively into a playable mobile game prototype before full-scale production.</p><p>Interactive 3D World Top Down: A playable vertical-slice prototype demonstrating top-down 3D navigation and camera control in a mobile game environment. Technology-Building Mechanics: Core interactive mechanics where players place, build, and configure functional technology components. Blockchain Activity Prototype: Interactive gameplay demonstrating transaction validation and tamper detection (verifying data blocks and identifying unauthorized changes). AI Activity Prototype: Hands-on activities demonstrating classification, learning from examples, and AI output evaluation. Interactive Missions and Quizzes: In-game educational challenges and checkpoints to assess player understanding of each concept. Technical Spike</p><p>Mobile 3D Top-Down Rendering: Test low-poly 3D models, top-down camera rendering, and mobile performance to ensure smooth gameplay on target mobile devices. Building &amp; Validation Logic: Stress-test the underlying algorithms for transaction validation and real-time tamper detection within the game engine. AI Example-Learning Simulation: Test lightweight sorting and pattern classification logic to ensure the &quot;learning from examples&quot; mechanic runs efficiently without heavy computational overhead. Assessment &amp; Quiz Architecture: Validate the state management for interactive missions, checkpoint quizzes, and player scoring. Target Player &amp; Market Needs Assessment</p><p>Target Players: Young learners aged 6–12 years old. Pilot Area: Cryptita Plays outreach and mini-library beneficiary sites of Cryptita Plays. Needs &amp; Problem Assessment: Blockchain and artificial intelligence concepts can be difficult for beginners to understand through traditional learning materials. Existing materials often rely on technical explanations rather than interactive experiences. Young learners have limited opportunities to explore these technologies through hands-on activities. Complex technology platforms may not be suitable as introductory learning environments for young learners. Sustainable Development Goal Target: Quality Education (SDG 4).</p><p>Pre-Production Feasibility Study</p><p>Area / Field Feasibility: Mobile Game Development focusing on an interactive 3D top-down perspective tailored for mobile deployment.</p><p>Educational Scope Feasibility: Structured strictly across three educational levels covering blockchain and AI, ensuring the curriculum is focused, achievable, and age-appropriate for 6–12 year olds.</p><p>Objectives &amp; Solutions: To develop a 3D world educational game that introduces fundamentals of blockchain and artificial intelligence concepts through interactive gameplay. To provide gameplay activities that demonstrate blockchain verification, tamper detection, AI classification, and AI output evaluation. To improve students&#39; engagement and understanding of emerging technologies through game-based learning. To provide educational challenges that assess players&#39; understanding of each concept.</p></div>',1)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
